// ---- the hand-editable text form (docs/SPEC-TABLES.md §16.9) ----

#ifndef BLOCKHOME_SCHEMA_TABLE_TEXTFORM_EDIT
#define BLOCKHOME_SCHEMA_TABLE_TEXTFORM_EDIT
// TableTextFormEdit replaces one existing scalar value (§16.9.3): path
// names it as "field", "field[2]" or "field.child", and text is its
// replacement spelling, one token of this form.
struct TableTextFormEdit
{
    const char * path;
    const char * text;
};
#endif // BLOCKHOME_SCHEMA_TABLE_TEXTFORM_EDIT

// PartRowLoadTextForm reads one PartRow from the hand-editable text form
// (docs/SPEC-TABLES.md §16.9): the strict s-expression document, resolved
// against the field kinds and landed through the JSON walk. A refusal
// names itself in *refusal (§16.9.4).
bool PartRowLoadTextForm( const char * text, int64_t bytes, PartRow & value, const char ** refusal );

// PartRowLoadTextForm with the DOCUMENT retains the source bytes (§16.9.3):
// *document and *document_bytes are the caller's own text, so a read then
// PartRowSaveTextForm with no edit is the input byte for byte.
bool PartRowLoadTextForm( const char * text, int64_t bytes, const char ** document, int64_t * document_bytes, PartRow & value, const char ** refusal );

// PartRowSaveTextForm writes the document a Load or Edit returned
// (docs/SPEC-TABLES.md §16.9.3): the retained bytes, so a read then a
// write with no edit is the input byte for byte. It answers the byte
// count, or -1 when capacity cannot hold the document.
int64_t PartRowSaveTextForm( const char * document, int64_t document_bytes, char * buffer, int64_t capacity );

// PartRowEditTextForm replaces existing scalar values (§16.9.3): each edit's
// token span and nothing else, all spans taken from the original document,
// a semantic no-op keeping the old spelling. On success *edited_bytes is
// the edited document's length; a short buffer answers false with
// *edited_bytes set to what it needs. A refusal names itself in *refusal
// and leaves the old document untouched.
bool PartRowEditTextForm( const char * document, int64_t document_bytes, const TableTextFormEdit * edits, int64_t count, char * buffer, int64_t capacity, int64_t * edited_bytes, PartRow & value, const char ** refusal );

// PartFrameLoadTextForm reads one PartFrame from the hand-editable text form
// (docs/SPEC-TABLES.md §16.9): the strict s-expression document, resolved
// against the field kinds and landed through the JSON walk. A refusal
// names itself in *refusal (§16.9.4).
bool PartFrameLoadTextForm( const char * text, int64_t bytes, PartFrame & value, const char ** refusal );

// PartFrameLoadTextForm with the DOCUMENT retains the source bytes (§16.9.3):
// *document and *document_bytes are the caller's own text, so a read then
// PartFrameSaveTextForm with no edit is the input byte for byte.
bool PartFrameLoadTextForm( const char * text, int64_t bytes, const char ** document, int64_t * document_bytes, PartFrame & value, const char ** refusal );

// PartFrameSaveTextForm writes the document a Load or Edit returned
// (docs/SPEC-TABLES.md §16.9.3): the retained bytes, so a read then a
// write with no edit is the input byte for byte. It answers the byte
// count, or -1 when capacity cannot hold the document.
int64_t PartFrameSaveTextForm( const char * document, int64_t document_bytes, char * buffer, int64_t capacity );

// PartFrameEditTextForm replaces existing scalar values (§16.9.3): each edit's
// token span and nothing else, all spans taken from the original document,
// a semantic no-op keeping the old spelling. On success *edited_bytes is
// the edited document's length; a short buffer answers false with
// *edited_bytes set to what it needs. A refusal names itself in *refusal
// and leaves the old document untouched.
bool PartFrameEditTextForm( const char * document, int64_t document_bytes, const TableTextFormEdit * edits, int64_t count, char * buffer, int64_t capacity, int64_t * edited_bytes, PartFrame & value, const char ** refusal );

